    /**
     * 递归扫描生成文档的结构：任何 object 必须有非空 properties 或显式 additionalProperties
     * （或属经核准的显式不透明声明）；任何 array 必须有带 type/$ref 的 items。
     * @return 问题列表（含完整路径）
     */
    static List<String> findStructureProblems(JsonNode schemas) {
        List<String> problems = new ArrayList<>();
        if (schemas == null || !schemas.isObject()) return problems;
        for (Iterator<String> it = schemas.fieldNames(); it.hasNext();) {
            String name = it.next();
            scanNode(schemas.path(name), name, schemas, problems);
        }
        return problems;
    }

    private static void scanNode(JsonNode node, String path, JsonNode schemas, List<String> problems) {
        if (node == null || !node.isObject()) {
            return;
        }
        if (node.has("$ref")) {
            return; // 由被引用 schema 单独扫描
        }
        String type = node.path("type").asText("");
        boolean hasProps = node.path("properties").isObject() && node.path("properties").size() > 0;
        boolean hasAdditional = node.has("additionalProperties");
        boolean objectish = "object".equals(type)
                || (type.isEmpty() && (node.has("properties") || hasAdditional));
        if (objectish) {
            String desc = node.path("description").asText("");
            boolean approvedOpaque = desc.contains(ApiDocsApplier.OPAQUE_MARKER)
                    && APPROVED_OPAQUE_FIELDS.contains(path);
            if (!hasProps && !hasAdditional && !approvedOpaque) {
                problems.add("嵌套空虚对象（无 properties 且无显式 additionalProperties）: " + path
                        + " = " + node);
            }
        }
        if ("array".equals(type)) {
            JsonNode items = node.path("items");
            if (!items.isObject() || (!items.has("type") && !items.has("$ref"))) {
                problems.add("数组缺少带 type/$ref 的 items: " + path + " = " + node);
            }
        }
        JsonNode props = node.path("properties");
        if (props.isObject()) {
            for (Iterator<String> it = props.fieldNames(); it.hasNext();) {
                String p = it.next();
                scanNode(props.path(p), path + "." + p, schemas, problems);
            }
        }
        if ("array".equals(type)) {
            scanNode(node.path("items"), path + "[]", schemas, problems);
        }
        JsonNode add = node.get("additionalProperties");
        if (add != null && add.isObject()) {
            scanNode(add, path + ".*", schemas, problems);
        }
    }
