    @SuppressWarnings("unchecked")
    private static void copySiblingKeywords(Schema<?> from, Schema<?> to) {
        if (from.getNullable() != null) {
            to.setNullable(from.getNullable());
        }
        if (from.getReadOnly() != null) {
